// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.database.entityimport androidx.room.ColumnInfoimport androidx.room.Entityimport androidx.room.Indeximport androidx.room.PrimaryKey/** * NOUS — KG entity (Table 5). * * Knowledge graph node. 12 entity types (PERSON, ORGANIZATION, etc.). * Supports aliases for deduplication and Bayesian confidence. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§4 KG Design</a> */@Entity(    tableName = "kg_entities",    indices = [        Index("type"),        Index("canonical_name"),        Index(value = ["type", "canonical_name"], unique = true),    ],)data class KgEntityEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "type")    val type: String,  // PERSON, ORGANIZATION, LOCATION, etc.    @ColumnInfo(name = "canonical_name")    val canonicalName: String,    @ColumnInfo(name = "aliases")    val aliases: String? = null,  // JSON array    @ColumnInfo(name = "metadata")    val metadata: String? = null,  // JSON map    @ColumnInfo(name = "confidence_alpha")    val confidenceAlpha: Float = 1.0f,    @ColumnInfo(name = "confidence_beta")    val confidenceBeta: Float = 1.0f,    @ColumnInfo(name = "mention_count")    val mentionCount: Int = 0,    @ColumnInfo(name = "last_mentioned")    val lastMentioned: Long? = null,    @ColumnInfo(name = "is_deleted")    val isDeleted: Boolean = false,    @ColumnInfo(name = "created_at")    val createdAt: Long,    @ColumnInfo(name = "updated_at")    val updatedAt: Long,) {    val confidence: Float        get() = confidenceAlpha / (confidenceAlpha + confidenceBeta)}/** * NOUS — KG edge (Table 6). * * Knowledge graph relationship. 20 edge types (KNOWS, WORKS_AT, etc.). * Supports temporal versioning via [supersededBy] and Bayesian confidence. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§4 KG Design</a> */@Entity(    tableName = "kg_edges",    indices = [        Index("source_entity_id"),        Index("target_entity_id"),        Index("edge_type"),        Index("superseded_by"),        Index(value = ["source_entity_id", "target_entity_id", "edge_type"], unique = true),    ],    // ForeignKeys removed — enforced via migration SQL instead    // (KSP has issues resolving cross-file ForeignKey references))data class KgEdgeEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "source_entity_id")    val sourceEntityId: Long,    @ColumnInfo(name = "target_entity_id")    val targetEntityId: Long,    @ColumnInfo(name = "edge_type")    val edgeType: String,  // KNOWS, WORKS_AT, LIKES, etc.    @ColumnInfo(name = "confidence_alpha")    val confidenceAlpha: Float = 1.0f,    @ColumnInfo(name = "confidence_beta")    val confidenceBeta: Float = 1.0f,    @ColumnInfo(name = "valid_from")    val validFrom: Long,    @ColumnInfo(name = "valid_to")    val validTo: Long? = null,    @ColumnInfo(name = "superseded_by")    val supersededBy: Long? = null,    @ColumnInfo(name = "source")    val source: String,  // user_explicit, user_implicit, inferred, llm_extracted    @ColumnInfo(name = "metadata")    val metadata: String? = null,    @ColumnInfo(name = "is_deleted")    val isDeleted: Boolean = false,    @ColumnInfo(name = "created_at")    val createdAt: Long,    @ColumnInfo(name = "updated_at")    val updatedAt: Long,) {    val confidence: Float        get() = confidenceAlpha / (confidenceAlpha + confidenceBeta)}